(FALSE, NULL, 'We cannot be more sensitive...', 'Alan Watts', 'Life', 'en', 'We cannot be more sensitive to pleasure without being more sensitive to pain.', 13, 77, 'SHORT', NOW(), NOW()),
(FALSE, NULL, 'Never pretend to a love...', 'Alan Watts', 'Love', 'en', 'Never pretend to a love which you do not actually feel, for love is not ours to command.', 18, 88, 'SHORT', NOW(), NOW()),
(FALSE, NULL, 'But I\'ll tell you what...', 'Alan Watts', 'Nature', 'en', 'But I\'ll tell you what hermits realize. If you go off into a far, far forest and get very quiet, you\'ll come to understand that you\'re connected with everything.', 29, 161, 'MEDIUM', NOW(), NOW()),
