(FALSE, NULL, 'Finding good players is easy....', 'Casey Stengel', 'Sports', 'en', 'Finding good players is easy. Getting them to play as a team is another story.', 15, 78, 'SHORT', NOW(), NOW()),
(FALSE, NULL, 'Fans don\'t boo nobodies.', 'Reggie Jackson (basketball, born 1990)', 'Sports', 'en', 'Fans don\'t boo nobodies.', 4, 24, 'SHORT', NOW(), NOW()),
